<?php use App\Core\Helpers as H; use App\Services\AdminPermissionService; $canManage=H::canAdmin('users.manage'); ?>
<header class="dashboard-heading"><div><h1>Users</h1><p class="muted">Manage account status and, when authorized, Admin access.</p></div></header>
<div class="responsive-table"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Account actions</th></tr></thead><tbody>
<?php foreach($users as $user): $canonical=$canonicalOwnerId!==null&&(int)$user['id']===(int)$canonicalOwnerId; $grants=array_filter(explode(',',(string)$user['permission_keys'])); ?><tr><td><?=H::e($user['name'])?></td><td><?=H::e($user['email'])?></td><td><?=H::e($user['role'])?></td><td><?=H::e($user['status'])?></td><td>
<?php if($canManage&&!$canonical&&($user['role']!=='admin'||$fullAccessAdmin)): ?><form method="post" action="/admin/users" class="inline"><input type="hidden" name="_csrf" value="<?=H::csrf()?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=(int)$user['id']?>"><input type="hidden" name="status" value="<?=$user['status']==='active'?'disabled':'active'?>"><button class="btn"><?=$user['status']==='active'?'Disable':'Enable'?></button></form><?php endif; ?>
<?php if($fullAccessAdmin): ?><details><summary><?=$user['role']==='admin'?'Edit Admin access':'Promote to Admin'?></summary><form method="post" action="/admin/users"><input type="hidden" name="_csrf" value="<?=H::csrf()?>"><input type="hidden" name="action" value="save_admin"><input type="hidden" name="id" value="<?=(int)$user['id']?>"><label><input type="checkbox" name="full_access" value="1" <?=((int)$user['full_access']===1)?'checked':''?> <?=$canonical?'disabled':''?>> Full access</label><?php if($canonical):?><input type="hidden" name="full_access" value="1"><?php endif;?><fieldset><legend>Granular permissions</legend><?php foreach($permissionRegistry as $permission):?><label><input type="checkbox" name="permissions[]" value="<?=H::e($permission)?>" <?=in_array($permission,$grants,true)?'checked':''?>> <?=H::e($permission)?></label><?php endforeach;?></fieldset><button class="btn">Save Admin access</button></form></details><?php endif; ?>
<?php if($canManage&&(int)$user['id']!==(int)H::user()['id']&&$user['role']!=='admin'):?><details class="permanent-delete"><summary>Permanent delete</summary><form method="post" action="/admin/users/<?=(int)$user['id']?>/delete" class="permanent-delete-form"><input type="hidden" name="_csrf" value="<?=H::csrf()?>"><label>Type <?=H::e($user['email'])?> to permanently delete<input type="email" name="confirm_email" required autocomplete="off"></label><button class="danger-button">Permanently delete user</button></form></details><?php endif;?>
</td></tr><?php endforeach;?></tbody></table></div>
